def stable_unique(items):
    def deep_eq(a, b):
        if type(a) != type(b):
            return False
        if isinstance(a, (int, str)):
            return a == b
        if isinstance(a, tuple):
            if len(a) != len(b):
                return False
            return all(deep_eq(x, y) for x, y in zip(a, b))
        if isinstance(a, list):
            if len(a) != len(b):
                return False
            return all(deep_eq(x, y) for x, y in zip(a, b))
        if isinstance(a, dict):
            if len(a) != len(b):
                return False
            for key in a:
                if key not in b:
                    return False
                if not deep_eq(a[key], b[key]):
                    return False
            return True
        return False

    if not items:
        return []

    result = []
    for item in items:
        found = False
        for existing in result:
            if deep_eq(item, existing):
                found = True
                break
        if not found:
            result.append(item)

    return result
