def top_k_counts(words: list[str], k: int) -> list[tuple[str, int]]:
    if k <= 0:
        return []

    word_info = {}

    for idx, word in enumerate(words):
        lower_word = word.lower()
        if lower_word not in word_info:
            word_info[lower_word] = {'count': 1, 'first_spelling': word, 'first_index': idx}
        else:
            word_info[lower_word]['count'] += 1

    items = []
    for info in word_info.values():
        items.append((info['first_spelling'], info['count'], info['first_index']))

    items.sort(key=lambda x: (-x[1], x[2]))

    return [(word, count) for word, count, _ in items[:k]]
