import json
import math
from collections import defaultdict

def parse_jsonl_metrics(lines: list[str]) -> dict:
    invalid = 0
    services = defaultdict(lambda: {"count": 0, "ok_count": 0, "latencies": []})

    for line in lines:
        line = line.strip()
        if not line:
            continue

        try:
            record = json.loads(line)
        except json.JSONDecodeError:
            invalid += 1
            continue

        if not isinstance(record, dict):
            invalid += 1
            continue

        required = ["service", "latency_ms", "status"]
        if not all(key in record for key in required):
            invalid += 1
            continue

        if not isinstance(record["service"], str):
            invalid += 1
            continue

        if not isinstance(record["latency_ms"], (int, float)):
            invalid += 1
            continue

        if not isinstance(record["status"], (int, float)):
            invalid += 1
            continue

        service = record["service"]
        latency = record["latency_ms"]
        status = int(record["status"])

        services[service]["count"] += 1
        services[service]["latencies"].append(latency)
        if 200 <= status < 300:
            services[service]["ok_count"] += 1

    result = {"invalid": invalid}

    for service in sorted(services.keys()):
        data = services[service]
        n = data["count"]
        if n == 0:
            p95 = None
        else:
            latencies_sorted = sorted(data["latencies"])
            idx = math.ceil(0.95 * n) - 1
            p95 = latencies_sorted[idx]

        result[service] = {
            "count": n,
            "ok_rate": data["ok_count"] / n if n > 0 else 0.0,
            "p95_latency_ms": p95
        }

    return result
