class CycleError(Exception):
    def __init__(self, cycle):
        self.cycle = cycle
        super().__init__(f"Cycle detected: {cycle}")

def dependency_plan(nodes: list[str], edges: list[tuple[str, str]]) -> list[str]:
    # Check for unknown nodes
    node_set = set(nodes)
    for a, b in edges:
        if a not in node_set or b not in node_set:
            raise ValueError(f"Node in edges not found in nodes: {a if a not in node_set else b}")

    # Remove duplicate edges and check for self-loops
    unique_edges = list(set(edges))
    for a, b in unique_edges:
        if a == b:
            raise CycleError([a, a])

    # Build graph and in-degree map
    graph = {node: [] for node in nodes}
    in_degree = {node: 0 for node in nodes}

    for a, b in unique_edges:
        graph[a].append(b)
        in_degree[b] += 1

    # Topological sort using Kahn's algorithm with min-heap
    import heapq

    # Initialize heap with nodes having zero in-degree
    heap = [node for node in nodes if in_degree[node] == 0]
    heapq.heapify(heap)

    result = []
    visited = set()

    while heap:
        current = heapq.heappop(heap)
        if current in visited:
            continue
        visited.add(current)
        result.append(current)

        # Reduce in-degree for neighbors
        for neighbor in graph[current]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0 and neighbor not in visited:
                heapq.heappush(heap, neighbor)

    # Check for cycles
    if len(result) != len(nodes):
        # Find a cycle in the remaining nodes
        remaining_nodes = [node for node in nodes if node not in visited]

        # Build subgraph of remaining nodes
        subgraph = {node: [neighbor for neighbor in graph[node] if neighbor in remaining_nodes] 
                    for node in remaining_nodes}

        # DFS to find cycle
        def find_cycle(start, visited_local):
            stack = [(start, [start])]
            while stack:
                node, path = stack.pop()
                visited_local.add(node)
                for neighbor in subgraph[node]:
                    if neighbor == start:
                        return path + [neighbor]
                    if neighbor not in visited_local:
                        stack.append((neighbor, path + [neighbor]))
            return None

        # Try to find cycle from each remaining node
        visited_local = set()
        for node in remaining_nodes:
            if node not in visited_local:
                cycle = find_cycle(node, visited_local)
                if cycle:
                    raise CycleError(cycle)

        # Fallback: if no cycle found through DFS, use in-degree analysis
        # This shouldn't happen if algorithm is correct
        raise CycleError([remaining_nodes[0]])

    return result
