def streaming_group_sum(rows):
    class _StreamingGroupSum:
        def __init__(self, rows):
            self.rows = rows
            self.invalid_count = 0
            self._totals = {}
            self._key_order = []
            self._done = False
            self._gen = None

        def __iter__(self):
            for row in self.rows:
                try:
                    _, key, value = row
                except (ValueError, TypeError):
                    self.invalid_count += 1
                    continue

                if not isinstance(value, (int, float)):
                    self.invalid_count += 1
                    continue

                if key not in self._totals:
                    self._totals[key] = 0
                    self._key_order.append(key)
                self._totals[key] += value

            self._gen = iter(
                (k, self._totals[k]) for k in self._key_order
            )
            self._done = True
            return self

        def __next__(self):
            if not self._done:
                self.__iter__()
            return next(self._gen)

    return _StreamingGroupSum(rows)
