import copy

def apply_patch_ops(document: dict, operations) -> dict:
    working_doc = copy.deepcopy(document)

    def _apply_operation(op, path, value):
        keys = path.split('.')
        if op == 'set':
            current = working_doc
            for key in keys[:-1]:
                if key not in current:
                    current[key] = {}
                current = current[key]
            current[keys[-1]] = value
        elif op == 'delete':
            current = working_doc
            for key in keys[:-1]:
                if key not in current:
                    return
                current = current[key]
            last_key = keys[-1]
            if last_key in current:
                del current[last_key]
        elif op == 'increment':
            current = working_doc
            for key in keys[:-1]:
                if key not in current:
                    raise ValueError(f"Path does not exist: {path}")
                current = current[key]
            last_key = keys[-1]
            if last_key not in current:
                raise ValueError(f"Path does not exist: {path}")
            current_value = current[last_key]
            if not isinstance(current_value, (int, float)):
                raise TypeError(f"Value at path {path} is not numerical")
            if not isinstance(value, (int, float)):
                raise TypeError("Increment value is not numerical")
            current[last_key] = current_value + value
        else:
            raise ValueError(f"Unknown operation: {op}")

    for op, path, value in operations:
        _apply_operation(op, path, value)

    return working_doc
