import time
import threading
from collections import OrderedDict

_SENTINEL = object()


class TTLCache:
    def __init__(self, maxsize: int, ttl: float, *, clock=time.time):
        self._maxsize = maxsize
        self._ttl = ttl
        self._clock = clock
        self._order: OrderedDict = OrderedDict()
        self._data: dict = {}
        self._lock = threading.Lock()

    def _is_expired(self, exp_time: float) -> bool:
        return self._clock() >= exp_time

    def _move_to_end(self, key) -> None:
        self._order.move_to_end(key)

    def _remove(self, key) -> None:
        self._data.pop(key, None)
        self._order.pop(key, None)

    def _evict(self, new_key=_SENTINEL) -> None:
        # 仅在必须为新 key 腾空间时才驱逐
        if new_key is not _SENTINEL:
            if new_key in self._order:
                return  # 已存在，仅更新，不需驱逐
            if len(self._data) < self._maxsize:
                return  # 还有余量

        # 先尝试移除过期条目（从最旧开始扫描）
        for k in list(self._order):
            if k in self._data and self._is_expired(self._data[k][1]):
                self._remove(k)
                if new_key is not _SENTINEL and len(self._data) < self._maxsize:
                    return  # 已腾出空间

        # 无过期条目可回收时，驱逐 LRU 非过期条目
        if new_key is not _SENTINEL:
            for k in list(self._order):
                if k in self._data and not self._is_expired(self._data[k][1]):
                    self._remove(k)
                    return

    def get(self, key, default=None):
        with self._lock:
            if key in self._data:
                value, exp_time = self._data[key]
                if self._is_expired(exp_time):
                    self._remove(key)
                    return default
                self._move_to_end(key)
                return value
            return default

    def set(self, key, value) -> None:
        with self._lock:
            now = self._clock()
            if key in self._data:
                self._data[key] = (value, now + self._ttl)
                self._move_to_end(key)
            else:
                self._evict(new_key=key)
                self._data[key] = (value, now + self._ttl)
                self._order[key] = None
                self._evict()

    def delete(self, key) -> None:
        with self._lock:
            self._remove(key)

    def __len__(self):
        with self._lock:
            return len(self._data)
