import asyncio
from typing import List, Tuple, Any, Coroutine


async def run_with_deadline(
    coros: List[Coroutine], limit: int, timeout: float
) -> List[Tuple[str, Any]]:
    if not coros:
        return []

    sem = asyncio.Semaphore(limit)
    results: List[Tuple[str, Any]] = [None] * len(coros)

    async def _worker(idx: int, coro: Coroutine):
        async with sem:
            return await coro

    tasks = [
        asyncio.create_task(_worker(i, coro)) for i, coro in enumerate(coros)
    ]

    try:
        done, pending = await asyncio.wait(
            tasks,
            timeout=timeout,
            return_when=asyncio.FIRST_COMPLETED,
        )
    except asyncio.CancelledError:
        for t in tasks:
            if not t.done():
                t.cancel()
        await asyncio.gather(*tasks, return_exceptions=True)
        raise

    # 收割已完成的
    for task in done:
        idx = tasks.index(task)
        if task.cancelled():
            results[idx] = ("cancelled", None)
        else:
            exc = task.exception()
            if exc is None:
                results[idx] = ("ok", task.result())
            else:
                results[idx] = ("error", exc)

    # 超时 / 尚未完成的 → cancelled
    for task in pending:
        task.cancel()
    if pending:
        await asyncio.gather(*pending, return_exceptions=True)
        for task in pending:
            idx = tasks.index(task)
            results[idx] = ("cancelled", None)

    return results
