import threading
import collections

class BoundedQueue:
    def __init__(self, capacity):
        self._q = collections.deque()
        self._cap = capacity
        self._lock = threading.Lock()
        self._not_full = threading.Condition(self._lock)
        self._not_empty = threading.Condition(self._lock)
        self._closed = False

    def put(self, item):
        with self._not_full:
            if self._closed:
                raise RuntimeError("Queue is closed")
            while len(self._q) >= self._cap:
                if self._closed:
                    raise RuntimeError("Queue is closed")
                self._not_full.wait()
            if self._closed:
                raise RuntimeError("Queue is closed")
            self._q.append(item)
            self._not_empty.notify()

    def get(self):
        with self._not_empty:
            while len(self._q) == 0:
                if self._closed:
                    return None
                self._not_empty.wait()
            if self._closed and len(self._q) == 0:
                return None
            item = self._q.popleft()
            self._not_full.notify()
            return item

    def close(self):
        with self._lock:
            if self._closed:
                return
            self._closed = True
            self._not_full.notify_all()
            self._not_empty.notify_all()
