#!/bin/sh
# 用法: ./script.sh access.log
# 输入格式: timestamp<TAB>status<TAB>latency_ms<TAB>path (TAB 分隔)
# 输出格式: request_count 5xx_count p99_latency_ms path (空格分隔)
# 排序: 5xx_count 降序，path 升序
#
# p99 取法: 对每个 path 的所有 latency 值排序后，取第 ceil(0.99 * n) 个值 (n 为该 path 的请求数)。
#   这是严格的 99th percentile 计算，要求存储所有 latency 值。
#
# 资源开销: 
#   - 内存: 需为每个 path 的每个请求存储 latency 值，最坏情况为 O(total_requests)。
#     若文件 >1GB 且请求数极多，可能导致内存不足。但这是精确计算 p99 的直接方法。
#   - 时间: 对每个 path 的 latency 排序，总时间复杂度为 O(∑(n_i log n_i))，n_i 为每个 path 的请求数。
#
# 注意: 此脚本使用 GNU awk (gawk) 的 asort 函数进行排序。

awk -F '\t' '
BEGIN {
    # 初始化数组
}
{
    path = $4;
    cnt[path]++;
    if ($2 >= 500 && $2 < 600) {
        five_xx[path]++;
    }
    # 使用复合键存储 latency (path, index)，避免多维数组
    lat[path, cnt[path]] = $3;
}
END {
    for (path in cnt) {
        n = cnt[path];
        if (n > 0) {
            # 将当前 path 的 latency 提取到连续数组以便排序
            for (i = 1; i <= n; i++) {
                tmp[i] = lat[path, i];
            }
            asort(tmp);  # 升序排序 (GNU awk 扩展)
            p99_idx = int(0.99 * n) + 1;  # 99th percentile 索引 (1-based)
            p99_val = tmp[p99_idx];
            # 输出: 请求数, 5xx 数, p99 latency, path
            print cnt[path], (five_xx[path]+0), p99_val, path;
        }
    }
}' "$1" | sort -t' ' -k2,2rn -k4,4
